        "quote": "突然整只手抬不起来"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00151",
        "explanation": "The doctor adapted disclosure to the crowded-clinic privacy concern while preserving necessary clinical disclosure.",
        "quote": "等进诊室关上门见到主刀医生"
      },
      {
        "event_id": "lite_evt_00186",
        "explanation": "The privacy-adapted approach reduced resistance and enabled disclosure.",
        "quote": "稍微没那么抵触了"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "good",
