  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00130",
          "explanation": "The doctor normalized the patient's anxiety and avoided moralizing.",
          "quote": "他现在紧张是正常的"
        },
        {
          "event_id": "lite_evt_00186",
          "explanation": "The tailored reassurance meaningfully reduced the patient's resistance.",
          "quote": "稍微没那么抵触了"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repeatedly acknowledged fear and embarrassment, framed disclosure as protective rather than blameworthy, and used a privacy-preserving approach that reduced resistance and enabled the handoff.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00009",
          "explanation": "The doctor actively marked the sensitive-history concern for privacy handling during record review.",
          "quote": "做隐私/授权标注"
        },
        {
          "event_id": "lite_evt_00076",
          "explanation": "The doctor elicited the need for control details and medication information beyond a single glucose value.",
          "quote": "看不到血糖控制的全貌"
        }
      ],
      "completion": "partial",
      "explanation": "The doctor actively explored and integrated the privacy concern and missing diabetes-control information, but diabetes itself was volunteered at the outset rather than actively discovered as a previously hidden fact.",
      "ho_id": "HO2",
